mapper.update:
UPDATE sys_user
SET login_fail_count = 0,
    locked_until     = NULL,
    last_login_time  = #{loginTime}
WHERE id = #{id}

UPDATE sys_user
SET login_fail_count = #{loginFailCount},
    locked_until     = #{lockedUntil}
WHERE id = #{id}

UPDATE sys_user
SET status        = #{status},
    token_version = #{tokenVersion}
WHERE id = #{id}
